const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={query:'',category:'all',lang:'all',maxPrice:40,minRating:0,stockOnly:false,discountOnly:false,mode:'all',sort:'popular',page:1,perPage:12,view:'grid'};
let cart=JSON.parse(localStorage.getItem('kitabevi_cart')||'{}');
let favorites=JSON.parse(localStorage.getItem('kitabevi_fav')||'[]');
let recent=JSON.parse(localStorage.getItem('kitabevi_recent')||'[]');
let toastTimer;
let coverCache=JSON.parse(localStorage.getItem('kitabevi_cover_cache')||'{}');
const pendingCoverRequests={};
const localCover=b=>b.cover||b.fallback||'assets/covers/default.svg';
const bookKey=b=>`${b.title}||${b.author}`.toLowerCase();
const imgTag=(b,cls='')=>{const key=bookKey(b);const src=coverCache[key]||localCover(b);return `<img class="${cls}" src="${src}" data-book-key="${escapeHtml(key)}" data-title="${escapeHtml(b.title)}" data-author="${escapeHtml(b.author)}" data-fallback="${b.fallback||'assets/covers/default.svg'}" alt="${escapeHtml(b.title)} uzluk sekli" loading="lazy">`;};
const saveCoverCache=()=>{try{localStorage.setItem('kitabevi_cover_cache',JSON.stringify(coverCache))}catch(e){}};
const normalizeCoverUrl=u=>u?u.replace('http://','https://'):'';
async function googleApiCover(title,author){const q=encodeURIComponent(`intitle:${title} inauthor:${author}`);const r=await fetch(`https://www.googleapis.com/books/v1/volumes?q=${q}&maxResults=1`);if(!r.ok)return '';const d=await r.json();const item=d.items&&d.items[0];const links=item&&item.volumeInfo&&item.volumeInfo.imageLinks;return normalizeCoverUrl((links&&((links.thumbnail)||(links.smallThumbnail)||(links.small)||(links.medium)))||'')}
async function openLibrarySearchCover(title,author){const r=await fetch(`https://openlibrary.org/search.json?title=${encodeURIComponent(title)}&author=${encodeURIComponent(author)}&limit=1`);if(!r.ok)return '';const d=await r.json();const doc=d.docs&&d.docs[0];return doc&&doc.cover_i?`https://covers.openlibrary.org/b/id/${doc.cover_i}-L.jpg`:''}
async function resolveRemoteCover(title,author,key){if(coverCache[key])return coverCache[key];if(pendingCoverRequests[key])return pendingCoverRequests[key];pendingCoverRequests[key]=(async()=>{let url='';try{url=await googleApiCover(title,author)}catch(e){}if(!url){try{url=await openLibrarySearchCover(title,author)}catch(e){}}if(url){coverCache[key]=url;saveCoverCache()}delete pendingCoverRequests[key];return url})();return pendingCoverRequests[key]}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function money(v){return Number(v).toFixed(2)+' AZN'}
function save(){localStorage.setItem('kitabevi_cart',JSON.stringify(cart));localStorage.setItem('kitabevi_fav',JSON.stringify(favorites));localStorage.setItem('kitabevi_recent',JSON.stringify(recent));updateCounts()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
function attachImageFallbacks(root=document){$$('img[data-fallback]',root).forEach(img=>{if(img.dataset.bound==='1')return;img.dataset.bound='1';img.addEventListener('error',()=>{if(img.src!==img.dataset.fallback)img.src=img.dataset.fallback});const key=img.dataset.bookKey;if(!key)return;if(coverCache[key]&&img.src!==coverCache[key]){img.src=coverCache[key];return}resolveRemoteCover(img.dataset.title||'',img.dataset.author||'',key).then(url=>{if(url&&img.isConnected)img.src=url}).catch(()=>{})})}
function filteredBooks(){
 let arr=BOOKS.filter(b=>{const q=state.query.trim().toLowerCase();const matchQ=!q||(b.title+' '+b.author+' '+b.category).toLowerCase().includes(q);const matchCat=state.category==='all'||b.category===state.category;const matchLang=state.lang==='all'||b.lang===state.lang;const matchPrice=b.price<=state.maxPrice;const matchRating=b.rating>=state.minRating;const matchStock=!state.stockOnly||b.stock;const matchDiscount=!state.discountOnly||b.discount;const matchMode=state.mode==='all'||(state.mode==='new'&&b.new)||(state.mode==='bestseller'&&b.bestseller)||(state.mode==='discount'&&b.discount);return matchQ&&matchCat&&matchLang&&matchPrice&&matchRating&&matchStock&&matchDiscount&&matchMode});
 if(state.sort==='rating')arr.sort((a,b)=>b.rating-a.rating);if(state.sort==='low')arr.sort((a,b)=>a.price-b.price);if(state.sort==='high')arr.sort((a,b)=>b.price-a.price);if(state.sort==='az')arr.sort((a,b)=>a.title.localeCompare(b.title));if(state.sort==='popular')arr.sort((a,b)=>(b.bestseller-a.bestseller)||(b.rating-a.rating));return arr;
}
function renderBooks(){const arr=filteredBooks();const pages=Math.max(1,Math.ceil(arr.length/state.perPage));if(state.page>pages)state.page=pages;const start=(state.page-1)*state.perPage;const pageBooks=arr.slice(start,start+state.perPage);$('#resultInfo').textContent=`${arr.length} netice tapildi`;$('#bookGrid').className='book-grid'+(state.view==='list'?' list':'');$('#bookGrid').innerHTML=pageBooks.map(cardHtml).join('');$('#emptyState').classList.toggle('show',arr.length===0);renderPagination(pages);attachImageFallbacks($('#bookGrid'));}
function cardHtml(b){const fav=favorites.includes(b.id);return `<article class="book-card" data-id="${b.id}"><div class="cover-wrap" data-open="${b.id}">${imgTag(b)}<div class="badge-row">${b.new?'<span class="badge">YENI</span>':''}${b.discount?'<span class="badge sale">ENDIRIM</span>':''}</div><button class="fav-heart ${fav?'active':''}" data-fav="${b.id}" aria-label="Sevimlilere elave et">${fav?'♥':'♡'}</button></div><div class="book-info"><span class="book-cat">${b.category}</span><h3 class="book-title">${escapeHtml(b.title)}</h3><p class="book-author">${escapeHtml(b.author)}</p><div class="rating">★★★★★ <span>${b.rating}</span></div><div class="price-row"><span class="price">${money(b.price)}</span>${b.oldPrice?`<span class="old-price">${money(b.oldPrice)}</span>`:''}<span class="stock ${b.stock?'':'out'}">${b.stock?'Stokda':'Bitib'}</span></div><div class="card-actions"><button class="add-btn" data-add="${b.id}" ${b.stock?'':'disabled'}>Sebete at</button><button class="detail-btn" data-open="${b.id}">i</button></div></div></article>`}
function renderPagination(pages){let html='';for(let i=1;i<=pages;i++)html+=`<button class="${i===state.page?'active':''}" data-page="${i}">${i}</button>`;$('#pagination').innerHTML=html}
function setMode(mode){state.mode=mode;state.page=1;state.query='';$('#searchInput').value='';$('#catalogTitle').textContent=mode==='new'?'Yeni gelenler':mode==='bestseller'?'Bestseller':mode==='discount'?'Endirimli kitablar':'Butun kitablar';renderBooks();setTimeout(()=>$('#books').scrollIntoView({behavior:'smooth'}),20)}
function setCategory(cat){state.category=cat;state.page=1;$('#categoryFilter').value=cat;$$('.chip').forEach(x=>x.classList.toggle('active',x.dataset.category===cat));$('#catalogTitle').textContent=cat==='all'?'Butun kitablar':cat;renderBooks();$('#books').scrollIntoView({behavior:'smooth'})}
function toggleFav(id){id=Number(id);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();renderBooks();renderFavs();toast(favorites.includes(id)?'Sevimlilere elave edildi':'Sevimlilerden silindi')}
function addCart(id,qty=1){id=Number(id);cart[id]=(cart[id]||0)+qty;save();renderCart();toast('Sebete elave edildi')}
function changeQty(id,d){id=Number(id);cart[id]=(cart[id]||0)+d;if(cart[id]<=0)delete cart[id];save();renderCart()}
function updateCounts(){$('#favCount').textContent=favorites.length;$('#cartCount').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function renderCart(){const ids=Object.keys(cart).map(Number);if(!ids.length)$('#cartItems').innerHTML='<div class="drawer-empty">Sebet hele bosdur.</div>';else $('#cartItems').innerHTML=ids.map(id=>{const b=BOOKS.find(x=>x.id===id);return `<div class="cart-item">${imgTag(b)}<div><h4>${escapeHtml(b.title)}</h4><p>${money(b.price)}</p><div class="qty"><button data-qty="${id}" data-d="-1">−</button><b>${cart[id]}</b><button data-qty="${id}" data-d="1">+</button></div></div><button class="remove" data-remove-cart="${id}">Sil</button></div>`}).join('');const total=ids.reduce((s,id)=>{const b=BOOKS.find(x=>x.id===id);return s+b.price*cart[id]},0);$('#cartTotal').textContent=money(total);attachImageFallbacks($('#cartItems'))}
function renderFavs(){const bs=favorites.map(id=>BOOKS.find(b=>b.id===id)).filter(Boolean);$('#favItems').innerHTML=bs.length?bs.map(b=>`<div class="fav-item">${imgTag(b)}<div><h4>${escapeHtml(b.title)}</h4><p>${escapeHtml(b.author)}</p><button class="add-btn" data-add="${b.id}" ${b.stock?'':'disabled'}>Sebete at</button></div><button class="remove" data-fav="${b.id}">Sil</button></div>`).join(''):'<div class="drawer-empty">Sevimliler siyahisi bosdur.</div>';attachImageFallbacks($('#favItems'))}
function openDrawer(which){$('#backdrop').classList.add('show');$('#cartDrawer').classList.toggle('show',which==='cart');$('#favDrawer').classList.toggle('show',which==='fav')}
function closeDrawers(){$('#backdrop').classList.remove('show');$$('.drawer').forEach(d=>d.classList.remove('show'))}
function addRecent(id){id=Number(id);recent=[id,...recent.filter(x=>x!==id)].slice(0,6);save();renderRecent()}
function renderRecent(){const section=$('#recentSection');const bs=recent.map(id=>BOOKS.find(b=>b.id===id)).filter(Boolean);section.style.display=bs.length?'block':'none';$('#recentGrid').innerHTML=bs.map(b=>`<article class="mini-card" data-open="${b.id}">${imgTag(b)}<div><b>${escapeHtml(b.title)}</b><small>${money(b.price)}</small></div></article>`).join('');attachImageFallbacks($('#recentGrid'))}
function openBook(id){const b=BOOKS.find(x=>x.id===Number(id));if(!b)return;addRecent(b.id);const fav=favorites.includes(b.id);$('#bookModalContent').innerHTML=`<div class="book-detail">${imgTag(b)}<div><span class="book-cat">${b.category}</span><h2>${escapeHtml(b.title)}</h2><p class="author">${escapeHtml(b.author)}</p><div class="rating">★★★★★ <span>${b.rating} / 5</span></div><div class="detail-meta"><div><small>Dil</small><b>${b.lang}</b></div><div><small>ISBN</small><b>${b.isbn}</b></div><div><small>Stok</small><b>${b.stock?'Var':'Bitib'}</b></div></div><p class="detail-desc">${escapeHtml(b.description)}</p><div class="price-row"><span class="price">${money(b.price)}</span>${b.oldPrice?`<span class="old-price">${money(b.oldPrice)}</span>`:''}</div><div class="detail-actions"><button class="btn primary" data-add="${b.id}" ${b.stock?'':'disabled'}>Sebete elave et</button><button class="btn secondary" data-fav="${b.id}">${fav?'♥ Sevimlilerde':'♡ Sevimlilere elave et'}</button><button class="btn secondary" data-share-book="${b.id}">Paylas</button></div></div></div>`;attachImageFallbacks($('#bookModalContent'));showModal('#bookModal')}
function showModal(sel){$(sel).classList.add('show');$(sel).setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeModals(){$$('.modal').forEach(m=>{m.classList.remove('show');m.setAttribute('aria-hidden','true')});document.body.style.overflow=''}
function renderSuggest(){const q=$('#searchInput').value.trim().toLowerCase();const box=$('#searchSuggest');if(q.length<2){box.classList.remove('show');return}const found=BOOKS.filter(b=>(b.title+' '+b.author).toLowerCase().includes(q)).slice(0,5);box.innerHTML=found.map(b=>`<button class="suggest-item" data-open="${b.id}">${imgTag(b)}<span><b>${escapeHtml(b.title)}</b><small>${escapeHtml(b.author)} · ${money(b.price)}</small></span></button>`).join('')||'<div class="suggest-item">Netice tapilmadi</div>';box.classList.add('show');attachImageFallbacks(box)}
function applySearch(){state.query=$('#searchInput').value.trim();state.page=1;state.mode='all';$('#catalogTitle').textContent=state.query?`Axtaris: "${state.query}"`:'Butun kitablar';$('#searchSuggest').classList.remove('show');renderBooks();$('#books').scrollIntoView({behavior:'smooth'})}
function resetFilters(){Object.assign(state,{category:'all',lang:'all',maxPrice:40,minRating:0,stockOnly:false,discountOnly:false,page:1});$('#categoryFilter').value='all';$('#langFilter').value='all';$('#priceFilter').value=40;$('#priceLabel').textContent='40 AZN';$('#ratingFilter').value='0';$('#stockFilter').checked=false;$('#discountFilter').checked=false;$$('.chip').forEach(x=>x.classList.remove('active'));renderBooks()}
async function shareSite(){const data={title:document.title,text:'KitabEvi kataloquna bax',url:location.href};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(location.href);toast('Link kopyalandi')}}catch(e){}}
async function shareBook(id){const b=BOOKS.find(x=>x.id===Number(id));const data={title:b.title,text:`${b.title} - ${b.author}`,url:location.href.split('#')[0]+'#book-'+b.id};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.url);toast('Kitab linki kopyalandi')}}catch(e){}}
function randomBook(){openBook(BOOKS[Math.floor(Math.random()*BOOKS.length)].id)}

document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){addCart(add.dataset.add);return}const fav=e.target.closest('[data-fav]');if(fav){toggleFav(fav.dataset.fav);if($('#bookModal').classList.contains('show'))openBook(fav.dataset.fav);return}const open=e.target.closest('[data-open],[data-open-book]');if(open){openBook(open.dataset.open||open.dataset.openBook);$('#searchSuggest').classList.remove('show');return}const p=e.target.closest('[data-page]');if(p){state.page=Number(p.dataset.page);renderBooks();$('#books').scrollIntoView({behavior:'smooth'});return}const qty=e.target.closest('[data-qty]');if(qty){changeQty(qty.dataset.qty,Number(qty.dataset.d));return}const rem=e.target.closest('[data-remove-cart]');if(rem){delete cart[rem.dataset.removeCart];save();renderCart();return}const sb=e.target.closest('[data-share-book]');if(sb){shareBook(sb.dataset.shareBook);return}if(e.target.closest('[data-close-drawer]')||e.target.id==='backdrop')closeDrawers();if(e.target.closest('[data-close-modal]')||e.target.classList.contains('modal'))closeModals();const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();setMode(nav.dataset.nav);return}const cat=e.target.closest('[data-category]');if(cat){setCategory(cat.dataset.category);$('#catalogPanel').classList.remove('show');return}});
$('#searchInput').addEventListener('input',renderSuggest);$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')applySearch();if(e.key==='Escape')$('#searchSuggest').classList.remove('show')});$('#searchBtn').onclick=applySearch;
$('#categoryFilter').onchange=e=>setCategory(e.target.value);$('#langFilter').onchange=e=>{state.lang=e.target.value;state.page=1;renderBooks()};$('#priceFilter').oninput=e=>{state.maxPrice=Number(e.target.value);$('#priceLabel').textContent=e.target.value+' AZN';state.page=1;renderBooks()};$('#ratingFilter').onchange=e=>{state.minRating=Number(e.target.value);state.page=1;renderBooks()};$('#stockFilter').onchange=e=>{state.stockOnly=e.target.checked;state.page=1;renderBooks()};$('#discountFilter').onchange=e=>{state.discountOnly=e.target.checked;state.page=1;renderBooks()};$('#sortSelect').onchange=e=>{state.sort=e.target.value;renderBooks()};
$('#resetFilters').onclick=resetFilters;$('#clearGenre').onclick=()=>setCategory('all');$('#filterToggle').onclick=()=>$('#filters').classList.toggle('show');$$('[data-view]').forEach(b=>b.onclick=()=>{$$('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.view=b.dataset.view;renderBooks()});
$('#cartBtn').onclick=()=>{renderCart();openDrawer('cart')};$('#favBtn').onclick=()=>{renderFavs();openDrawer('fav')};$('#clearCart').onclick=()=>{cart={};save();renderCart();toast('Sebet temizlendi')};$('#checkoutBtn').onclick=()=>{if(!Object.keys(cart).length){toast('Sebet bosdur');return}closeDrawers();showModal('#checkoutModal')};
$('#checkoutForm').onsubmit=e=>{e.preventDefault();const order=Date.now().toString().slice(-8);localStorage.setItem('kitabevi_last_order',order);cart={};save();renderCart();closeModals();toast('Sifaris #'+order+' qebul edildi (demo)')};
$('#newsletterForm').onsubmit=e=>{e.preventDefault();localStorage.setItem('kitabevi_newsletter',$('#newsletterEmail').value);e.target.reset();toast('Abunelik yadda saxlandi')};
$('#catalogBtn').onclick=()=>{const p=$('#catalogPanel');p.classList.toggle('show');$('#catalogBtn').setAttribute('aria-expanded',p.classList.contains('show'))};$('#randomBtn').onclick=randomBook;$('#shareBtn').onclick=shareSite;$('#clearRecent').onclick=()=>{recent=[];save();renderRecent()};
$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('kitabevi_theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('kitabevi_theme')==='dark')document.body.classList.add('dark');
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawers();closeModals();$('#searchSuggest').classList.remove('show')}});
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#book-(\d+)$/);if(m)openBook(Number(m[1]))});
updateCounts();renderBooks();renderCart();renderFavs();renderRecent();attachImageFallbacks();if(location.hash.startsWith('#book-')){const id=Number(location.hash.split('-')[1]);if(id)openBook(id)}
